#!/usr/bin/env bash
#
# Compare a .config generated by 'make defconfig' with the request in
# .diffconfig: every symbol that was asked for has to survive the round trip,
# and nothing explicitly disabled may come back.
#
# This is the heart of the dry validation: it needs no compiler and no package
# build, but it does need the full source tree and every feed (the Kconfig
# metadata for a package only exists once the feed is installed). A symbol that
# disappears here would disappear in the real build too - usually because the
# package was renamed upstream, the feed is missing, or a dependency no longer
# resolves.
#
# kmod-* packages are special: Kconfig writes =m for them (they are kernel
# modules), so =y and =m are both accepted for CONFIG_PACKAGE_kmod-*.
#
# Usage: scripts/check-defconfig.sh <generated .config> [.diffconfig]
#
set -euo pipefail

config=${1:?usage: check-defconfig.sh <generated .config> [.diffconfig]}
diffconfig=${2:-.diffconfig}

[ -f "$config" ]     || { echo "::error::$config does not exist (did make defconfig run?)"; exit 1; }
[ -f "$diffconfig" ] || { echo "::error::$diffconfig does not exist"; exit 1; }

errors=0
checked=0

# Value of a symbol in the generated config: 'y'/'m'/'n'/the raw value, or
# empty when the symbol is not in the file at all.
generated() {
  local sym=$1 line
  line=$(grep -m1 -E "^CONFIG_${sym}=" "$config" || true)
  if [ -n "$line" ]; then
    printf '%s' "${line#CONFIG_"${sym}"=}"
  elif grep -qxE "# CONFIG_${sym} is not set" "$config"; then
    printf 'n'
  fi
}

lineno=0
while IFS= read -r raw || [ -n "$raw" ]; do
  lineno=$((lineno + 1))
  line=${raw%$'\r'}
  [ -z "$line" ] && continue

  if [ "${line:0:1}" = '#' ]; then
    [[ $line =~ ^#[[:space:]]+CONFIG_([A-Za-z0-9_]+)[[:space:]]+is[[:space:]]+not[[:space:]]+set$ ]] || continue
    sym=${BASH_REMATCH[1]}
    want='n'
  elif [[ $line =~ ^CONFIG_([A-Za-z0-9_]+)=(.*)$ ]]; then
    sym=${BASH_REMATCH[1]}
    want=${BASH_REMATCH[2]}
  else
    continue
  fi

  got=$(generated "$sym")
  checked=$((checked + 1))

  if [ "$want" = 'n' ]; then
    case "$got" in
      ''|n) : ;;
      *) echo "::error::$diffconfig:$lineno: CONFIG_$sym was disabled but the build config has '$got'"
         errors=$((errors + 1)) ;;
    esac
    continue
  fi

  # kmod packages are built as modules; anything else must match exactly.
  if [[ $sym =~ ^PACKAGE_kmod- ]]; then
    case "$got" in
      y|m) : ;;
      *) echo "::error::$diffconfig:$lineno: CONFIG_$sym=$want did not survive (build config has '${got:-<missing>}')"
         errors=$((errors + 1)) ;;
    esac
    continue
  fi

  if [ "$got" != "$want" ]; then
    echo "::error::$diffconfig:$lineno: CONFIG_$sym=$want did not survive (build config has '${got:-<missing>}')"
    errors=$((errors + 1))
  fi
done < "$diffconfig"

if [ "$errors" -ne 0 ]; then
  echo "::error::$errors of $checked requested symbol(s) did not survive make defconfig"
  exit 1
fi
echo "OK: all $checked requested symbol(s) survived make defconfig"
